'use strict';
const $ = (s) => document.querySelector(s);
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
 library:'M5 4h14v17l-7-4-7 4V4Z M9 8h6 M9 11h4',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',ask:'M12 3l2.7 6.3L21 12l-6.3 2.7L12 21l-2.7-6.3L3 12l6.3-2.7L12 3Z',plus:'M12 5v14 M5 12h14',arrow:'M9 5l7 7-7 7',back:'M15 5l-7 7 7 7',play:'M9 5l11 7-11 7V5Z',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',check:'M5 12l4 4L19 6',folder:'M3 7V5h6l2 2h10v13H3V7Z',share:'M12 16V2 M7 7l5-5 5 5 M5 11H3v11h18V11h-2',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',more:'M5 12h.1 M12 12h.1 M19 12h.1',link:'M10 13a5 5 0 0 0 7 .1l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7-.1l-3 3a5 5 0 0 0 7 7l2-2',send:'M12 20V4 M5 11l7-7 7 7',edit:'M15 4l5 5 M3 21l5-1L21 7l-5-5L3 15v6Z',globe:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M2 12h20 M12 2c6 6 6 14 0 20-6-6-6-14 0-20',book:'M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3V4Z M12 6v16',refresh:'M20 4v6h-6 M4 20v-6h6 M4 8a8 8 0 0 1 14-3l2 5 M4 14l2 5a8 8 0 0 0 14-3',info:'M12 11v6 M12 7h.1 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',leaf:'M20 3C7 1 1 10 6 17c8 7 16-1 14-14Z M5 20L16 9',pin:'M12 22s8-9 8-14a8 8 0 0 0-16 0c0 5 8 14 8 14Z M15 8a3 3 0 1 1-6 0 3 3 0 0 1 6 0'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.library}"/></svg>`;}
function art(kind){
 let body='';
 if(kind==='food'||kind==='salad'){
  const peas=Array.from({length:28},(_,i)=>{let a=i*2.4,r=14+Math.sqrt(i)*10;return `<ellipse cx="${125+Math.cos(a)*r}" cy="${104+Math.sin(a)*r*.7}" rx="8" ry="6" fill="${i%2?'#c58039':'#e4ab57'}" transform="rotate(${i*19} 125 104)"/><path d="M${124+Math.cos(a)*r} ${102+Math.sin(a)*r*.7}l3 2" stroke="#f4d7a3" stroke-width="1.5"/>`}).join('');
  body=`<rect width="250" height="200" fill="${kind==='salad'?'#e4ebd9':'#edd9be'}"/><path d="M0 25h250M0 28h250M0 166h250M0 169h250" stroke="#ffffff50"/><ellipse cx="128" cy="116" rx="89" ry="69" fill="#27352915"/><ellipse cx="122" cy="99" rx="88" ry="74" fill="#f7f5ec"/><ellipse cx="122" cy="99" rx="71" ry="60" fill="#d9d5c5"/><ellipse cx="122" cy="97" rx="67" ry="56" fill="#f7eecf"/>${peas}<g fill="#4f7442"><path d="M87 68c-18-21-28-5-14 6 5 4 11 2 14-6Z M91 71c11-22 22-13 15 0-6 9-13 5-15 0Z M151 124c-8-24-22-15-14 0 4 8 10 6 14 0Z M156 122c20-18 23 0 8 5l-8-5Z M125 75c-2-20-15-19-14-5 2 8 7 9 14 5Z M109 138c-10-21-21-15-14-2 3 7 9 7 14 2Z"/></g><g fill="#35613b"><ellipse cx="140" cy="84" rx="4" ry="2"/><ellipse cx="94" cy="110" rx="3" ry="2"/><ellipse cx="141" cy="103" rx="4" ry="2"/></g><path d="M194 145l33 4c-2 30-27 38-43 20Z" fill="#efc347"/><path d="M195 149l27 4c-4 22-20 27-33 15Z" fill="#fff0a7"/><path d="M213 185V65" stroke="#8a8b7f" stroke-width="5"/><path d="M206 61v26q7 8 14 0V61 M213 61v28" stroke="#8a8b7f" fill="none" stroke-width="2"/>`;
 } else if(kind==='japan'){
 body='<rect width="250" height="200" fill="#dfe9ee"/><circle cx="197" cy="34" r="20" fill="#f4d9b9"/><path d="M0 135L76 42l73 93Z" fill="#a9bcc3"/><path d="M53 71l23-29 25 31-23-9Z" fill="#eff5f5"/><path d="M0 126q62-28 125 0t125-10v84H0Z" fill="#90a698"/><path d="M0 150q54-16 115 1t135-10v59H0Z" fill="#567d69"/><path d="M68 200l57-87h15l16 87" fill="#d2c9ad"/><g fill="#ab493c"><path d="M65 79h132v12H65z M73 100h116v9H73z M87 85h10v92H87z M166 85h10v92h-10z"/><path d="M59 72q68 11 144 0l-7 13H66Z"/></g><path d="M14 0v200 M18 40l40-35 M14 70l45-29" stroke="#405d50" stroke-width="7"/><g fill="#789486"><circle cx="18" cy="17" r="27"/><circle cx="47" cy="13" r="26"/><circle cx="29" cy="53" r="22"/></g>';
 }else if(kind==='ideas'){
 body='<rect width="250" height="200" fill="#dae4f3"/><ellipse cx="136" cy="172" rx="80" ry="10" fill="#607a9b20"/><path d="M59 62l106-17 22 114-106 17Z" fill="#436ba3"/><path d="M69 55l109-5 6 112-109 5Z" fill="#f5f0df"/><path d="M120 55l4 108" stroke="#d0c6a9"/><path d="M79 77l30-1 M80 87l29-1 M80 97l29-1 M81 107l21-1 M137 83l29-1 M137 93l29-1 M137 103l23-1" stroke="#9faea9" stroke-width="3"/><path d="M183 145l31-100 5 2-30 100-7 9Z" fill="#ce7c43"/><path d="M123 24c-8-20 13-25 17-12 4 12-11 22-11 22" fill="#f0c661"/>';
 }else if(kind==='cafe'){
 body='<rect width="250" height="200" fill="#eedfc9"/><rect y="148" width="250" height="52" fill="#bc926a"/><rect x="20" y="20" width="105" height="117" rx="3" fill="#809883"/><path d="M72 20v117 M20 78h105" stroke="#e7d2b1" stroke-width="5"/><ellipse cx="170" cy="167" rx="39" ry="9" fill="#f4eee4"/><path d="M146 127h47v30q-23 19-47 0Z" fill="#f9f5ea"/><ellipse cx="170" cy="127" rx="23.5" ry="8" fill="#c09064"/><path d="M193 133c21-5 19 24 0 19" stroke="#f9f5ea" stroke-width="6" fill="none"/><path d="M57 156V93" stroke="#476a45" stroke-width="3"/><g fill="#648350"><ellipse cx="45" cy="107" rx="15" ry="6" transform="rotate(35 45 107)"/><ellipse cx="67" cy="118" rx="15" ry="6" transform="rotate(-35 67 118)"/></g><path d="M38 136h39l-6 36H44Z" fill="#c9764c"/>';
 }else{
 body='<rect width="250" height="200" fill="#e6ddeb"/><ellipse cx="131" cy="177" rx="60" ry="8" fill="#6d55801b"/><path d="M127 88h8v77h-8Z" fill="#a897ab"/><ellipse cx="131" cy="167" rx="32" ry="7" fill="#c4b3c5"/><path d="M67 102a64 64 0 0 1 128 0Z" fill="#be7064"/><ellipse cx="131" cy="102" rx="64" ry="8" fill="#e6ba8b"/><path d="M135 104v43" stroke="#7a656f" stroke-width="2"/><circle cx="135" cy="147" r="3" fill="#7a656f"/>';
 }
 return `<svg viewBox="0 0 250 200" preserveAspectRatio="xMidYMid slice" role="img" aria-label="${esc({food:'Illustration of chickpeas with herbs and lemon',salad:'Illustration of a fresh salad',japan:'Illustration of a Kyoto garden',ideas:'Illustration of an open notebook',cafe:'Illustration of a café',lamp:'Illustration of a table lamp'}[kind]||'Note illustration')}">${body}</svg>`;
}
const initialNotes=[
 {id:'kyoto',title:'A quieter side of Kyoto',type:'Places',art:'japan',summary:'Three small stops beyond the busy streets.',source:'YouTube',age:'Yesterday',url:'https://example.com/sample/kyoto',collections:['Japan, someday'],date:'recent'},
 {id:'ideas',title:'Make room for a little boredom',type:'Ideas',art:'ideas',summary:'Why your best ideas arrive in the gaps.',source:'Article',age:'Yesterday',url:'https://example.com/sample/boredom',collections:[],date:'recent'},
 {id:'noodles',title:'Ginger noodles for busy evenings',type:'Recipes',art:'food',summary:'A quick sauce, one pan, dinner in 15 minutes.',source:'Instagram',age:'2 days ago',url:'https://example.com/sample/noodles',collections:['Weeknight cooking'],date:'recent'},
 {id:'cafe',title:'Slow mornings in Bandra',type:'Places',art:'cafe',summary:'Two cafés for coffee and a long conversation.',source:'Instagram',age:'3 days ago',url:'https://example.com/sample/cafes',collections:['Around the city'],date:'recent'},
 {id:'salad',title:'The lemony white bean salad',type:'Recipes',art:'salad',summary:'Ten minutes. A proper lunch. No stove needed.',source:'Article',age:'Last week',url:'https://example.com/sample/salad',collections:['Weeknight cooking'],date:'older'},
 {id:'lamp',title:'A softer light for the living room',type:'Products',art:'lamp',summary:'A small table lamp with a warm, diffused glow.',source:'Website',age:'Last week',url:'https://example.com/sample/lamp',collections:['For the home'],date:'older'}
];
let persisted={};try{persisted=JSON.parse(localStorage.getItem('clipnote-design-v1')||'{}')}catch{}
let notes=Array.isArray(persisted.notes)?persisted.notes:structuredClone(initialNotes);
let collections=Array.isArray(persisted.collections)?persisted.collections:['Weeknight cooking','Japan, someday','Around the city','For the home'];
notes.forEach(n=>{n.template=n.template||(n.source==='AI'?'composed':initialNotes.find(x=>x.id===n.id)?.type==='Recipes'?'recipe':n.id.startsWith('saved-')&&n.type==='Recipes'?'recipe':'generic')});
const state={draft:'',resultQuery:'',tab:'library',segment:'Notes',filter:'All',collection:null,query:'',searchType:'All types',searchSource:'All sources',scope:'All notes',question:'',answer:null,detail:null,origin:'library',scroll:{},favorite:persisted.favorite||[],job:null};
function persist(){try{localStorage.setItem('clipnote-design-v1',JSON.stringify({notes,collections,favorite:state.favorite}))}catch{}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4200)}
function navigate(tab){if(!state.detail)state.scroll[state.tab]=$('#app').scrollTop;state.tab=tab;state.detail=null;history.pushState(null,'','#'+tab);render();$('#app').scrollTop=state.scroll[tab]||0;}
function openNote(id){state.scroll[state.tab]=$('#app').scrollTop;state.origin=state.tab;state.detail=id;history.pushState(null,'','#note/'+id);render();$('#app').scrollTop=0;}
function back(){state.detail=null;navigate(state.origin)}
function top(title,subtitle,save=state.tab==='ask'){return `<div class="topline"><div class="wordmark">${icon('library')}clipnote</div><button class="avatar" data-action="settings" aria-label="Open settings">YS</button></div><div class="title-row"><h1>${title}</h1>${save?`<button class="save-button" data-action="save">${icon('plus')} Save</button>`:''}</div>${subtitle?`<p class="subtle">${subtitle}</p>`:''}`}
function row(n){return `<button class="note-row" data-note="${esc(n.id)}"><div class="note-thumb">${art(n.art)}</div><div class="note-copy"><div class="type">${esc(n.type)}</div><h3>${esc(n.title)}</h3><p class="summary">${esc(n.summary)}</p><div class="metadata">${icon(n.source==='Instagram'||n.source==='YouTube'?'play':'globe')}${esc(n.source)} <span>· ${esc(n.age)}</span></div></div>${icon('arrow')}</button>`}
function library(){
 let html=top('Your library',`${notes.length} notes. A world of possibilities.`);
 html+=`<div class="segments" aria-label="Library view">${['Notes','Collections'].map(s=>`<button aria-pressed="${state.segment===s}" class="${state.segment===s?'selected':''}" data-segment="${s}">${s}</button>`).join('')}</div>`;
 if(state.segment==='Collections'){
  if(state.collection){const selected=notes.filter(n=>n.collections.includes(state.collection));return html+`<button class="collection-back" data-action="all-collections">${icon('back')} All collections</button><div class="section-head"><h2>${esc(state.collection)}</h2><button class="text-button" data-action="ask-collection">Ask these notes</button></div><p class="subtle">${selected.length} notes</p><div class="note-list">${selected.map(row).join('')||'<div class="empty"><h2>A space for your next idea</h2><p>Open a note and choose Add to collection to put it here.</p></div>'}</div>`}
  return html+`<div class="collection-intro"><strong>A place for a plan.</strong>Gather notes around something you want to do. One note can belong in a few places.</div><div class="section-head"><h2>Your collections</h2><button class="text-button" data-action="new-collection">New collection</button></div><div class="collection-grid">${collections.map((c,i)=>`<button class="collection-card" data-collection="${esc(c)}"><div class="collection-art">${art(['food','japan','cafe','lamp'][i%4])}</div><div class="collection-text"><h3>${esc(c)}</h3><p>${notes.filter(n=>n.collections.includes(c)).length} notes</p></div></button>`).join('')}</div>`;
 }
 const visible=notes.filter(n=>state.filter==='All'||(state.filter==='Favorites'?state.favorite.includes(n.id):n.type===state.filter));
 html+=`<div class="filters" aria-label="Filter by note type">${['All','Recipes','Places','Ideas','Products','Favorites'].map(f=>`<button aria-pressed="${state.filter===f}" class="${state.filter===f?'selected':''}" data-filter="${f}">${f}</button>`).join('')}</div>`;
 if(state.job)html+=`<button class="pending-line" data-action="job">${icon(state.job.status==='ready'?'check':'clock')}<span>${state.job.status==='ready'?'Your new note is ready':'Link saved. Making your note…'}</span>${icon('arrow')}</button>`;
 if(state.filter==='All')html+=`<div class="section-head"><h2>Pick up where you left off</h2></div><button class="continue-card" data-note="noodles"><div class="continue-copy"><div class="eyebrow">From your recipe notes</div><h3>Tonight, keep<br>it simple.</h3><p>Ginger noodles ${icon('arrow')}</p></div><div class="continue-art">${art('food')}</div></button>`;
 html+=`<div class="section-head"><h2>${state.filter==='All'?'Recently saved':state.filter}</h2><span class="subtle">${visible.length} notes</span></div><div class="note-list">${visible.map(row).join('')||`<div class="empty">${icon('heart')}<h2>Keep your favorites close</h2><p>Tap the heart on any note to find it here.</p></div>`}</div>`;
 return html;
}
function matches(){const q=state.query.toLowerCase().trim();let tokens=q.split(/\s+/).filter(t=>t.length>2&&!['the','for','with','that','saved','some'].includes(t));if(/dinner|cook|food|lunch|quick/.test(q))tokens.push('recipes');if(/japan|quiet|travel/.test(q))tokens.push('kyoto');return notes.filter(n=>(state.searchType==='All types'||n.type===state.searchType)&&(state.searchSource==='All sources'||n.source===state.searchSource)&&(!q||tokens.some(t=>`${n.title} ${n.summary} ${n.type} ${n.collections.join(' ')}`.toLowerCase().includes(t))))}
function search(){return top('Find a saved idea','A word, a place, or just what you remember.')+`<div class="search-box">${icon('search')}<input type="search" id="search-input" aria-label="Search notes" value="${esc(state.query)}" placeholder="Something quick for dinner" autocomplete="off"><button class="clear" data-action="clear-search" aria-label="Clear search">×</button></div><div class="search-filter"><label>Note type<select id="search-type">${['All types','Recipes','Places','Ideas','Products'].map(s=>`<option ${s===state.searchType?'selected':''}>${s}</option>`).join('')}</select></label><label>Source<select id="search-source">${['All sources','Instagram','YouTube','Article','Website'].map(s=>`<option ${s===state.searchSource?'selected':''}>${s}</option>`).join('')}</select></label></div><div id="search-results">${searchResults()}</div>`}
function searchResults(){if(!state.query&&state.searchType==='All types'&&state.searchSource==='All sources')return `<div class="section-head"><h2>Try remembering a little</h2></div>${['Something quick for dinner','That quiet place in Japan','Ideas for my living room'].map(s=>`<button class="suggestion" data-query="${esc(s)}">${icon('search')}<span>${s}</span><span class="arrow">↖</span></button>`).join('')}<div class="small-panel space-top"><h3>Your words are enough.</h3><p>In the finished app, search will match ideas as well as titles. This prototype uses a small set of sample matches.</p></div>`;
 const found=matches();return `<div class="section-head"><h2>${found.length} ${found.length===1?'note':'notes'} found</h2><button class="text-button" data-action="reset-filters">Reset filters</button></div>${found.length?`<div class="note-list">${found.map(row).join('')}</div><button class="secondary" data-action="ask-results">Ask about these ${found.length} notes</button>`:`<div class="empty">${icon('search')}<h2>No notes match yet</h2><p>Try a different word or clear your filters. Your other notes are still in your library.</p><button class="secondary" data-action="reset-search">Clear search and filters</button></div>`}`}
function scopeNotes(){if(state.scope==='Search results')return (state.resultIds||[]).map(id=>notes.find(n=>n.id===id)).filter(Boolean);if(state.scope.startsWith('Note:'))return notes.filter(n=>n.id===state.scope.slice(5));return state.scope==='All notes'?notes:notes.filter(n=>n.collections.includes(state.scope))}
function scopeLabel(){return state.scope.startsWith('Note:')?(notes.find(n=>n.id===state.scope.slice(5))?.title||'This note'):state.scope}
function ask(){const scopes=['All notes',...collections,...(state.scope==='Search results'?['Search results']:[]),...(state.scope.startsWith('Note:')?[state.scope]:[])];return top('Ask your library','Turn what you saved into something useful.')+`<label class="scope-select">Use <select id="ask-scope" aria-label="Notes to use for this answer">${scopes.map(s=>`<option value="${esc(s)}" ${s===state.scope?'selected':''}>${esc(s.startsWith('Note:')?scopeLabel():s)}</option>`).join('')}</select></label>${state.scope==='Search results'?`<p class="hint">From search: ${esc(state.resultQuery)}</p>`:''}${state.answer?answerView():`<div class="ask-intro"><div class="ask-mark">${icon('ask')}</div><h2>Your notes.<br>A new way to use them.</h2><p>Find a connection, make a plan, or figure out what’s for dinner.</p></div>${['What can I cook in 20 minutes?','Plan a quiet afternoon in Kyoto','What did I save about creativity?'].map((q,i)=>`<button class="question-card" data-question="${esc(q)}">${icon(['leaf','pin','book'][i])}<span>${q}</span>${icon('arrow')}</button>`).join('')}`}<form id="ask-form" class="composer"><textarea id="question" rows="1" aria-label="Ask a question" placeholder="Ask about your saved notes…">${esc(state.draft)}</textarea><button aria-label="Send question">${icon('send')}</button></form><p class="demo-caption">Scripted demo answers · Your sample notes stay private.</p>`}
function answerView(){const a=state.answer;return `<div class="bubble">${esc(state.question)}</div><div class="answer-header">${icon('ask')} From your notes</div><div class="answer">${a.html}</div>${a.ids.length?`<p class="coverage">Used ${a.ids.length} of ${a.total} notes in ${esc(scopeLabel().toLowerCase())}. ${a.total>a.ids.length?'Other notes were not used.':'All scoped notes were considered.'}</p><div aria-label="Source notes">${a.ids.map((id,i)=>`<button class="source-chip" data-note="${id}">${i+1}. ${esc(notes.find(n=>n.id===id).title)}</button>`).join('')}</div><button class="secondary space-top" data-action="save-answer">${icon('library')} ${a.savedId?'Open saved note':'Save answer as a note'}</button>`:''}<button class="text-button" data-action="new-question">Start a new question</button>`}
function generateAnswer(question){state.question=question;state.draft='';const pool=scopeNotes();const q=question.toLowerCase();let selected=[],html='',title='';
 if(/dinner|cook|recipe|lunch|minutes/.test(q)){selected=pool.filter(n=>n.type==='Recipes').slice(0,2);title='A simple dinner plan';html=`<p>You have ${selected.length===1?'one easy option':'a couple of easy options'} for an evening with very little cooking.</p><ol>${selected.map(n=>`<li><strong>${esc(n.title)}</strong><br>${esc(n.summary)}</li>`).join('')}</ol><p>Pick one for tonight, and keep the other for another day.</p>`}
 else if(/kyoto|japan|afternoon/.test(q)){selected=pool.filter(n=>n.id==='kyoto');title='A quiet afternoon in Kyoto';html='<p>Keep the afternoon to one area so there’s room to wander.</p><ol><li><strong>Start with the garden.</strong><br>Take your time along the quieter paths.</li><li><strong>Walk to the small bookshop.</strong><br>Leave a little room for an unexpected find.</li><li><strong>Finish with tea.</strong><br>Check opening hours before you go.</li></ol><p>This is a suggested order based on the sample note, not verified travel guidance.</p>'}
 else if(/creative|creativity|boredom|ideas/.test(q)){selected=pool.filter(n=>n.id==='ideas');title='Leave a little room for ideas';html='<p>Your note suggests leaving some unfilled time in the day: take a walk without headphones, keep a notebook close, and resist filling every pause with a screen.</p><p>The useful action: leave ten minutes open after your next task.</p>'}
 if(!selected.length){html='<p>This demo doesn’t have a supported answer for that question in the selected notes.</p><p>Try a suggested question, or change the note scope. In the finished app, this state must distinguish missing evidence from an AI service error.</p>';title=''}
 state.answer={html,ids:selected.map(n=>n.id),total:pool.length,title};render();$('#app').scrollTop=0;
}
function detail(){const n=notes.find(n=>n.id===state.detail);if(!n)return '<div class="empty"><h2>Note unavailable</h2><button class="primary" data-action="back">Back to library</button></div>';const recipe=n.template==='recipe';return `<div class="backbar"><button data-action="back">${icon('back')}${state.origin==='ask'?'Answer':state.origin==='search'?'Results':'Library'}</button><div class="toolbar"><button data-action="favorite" aria-label="${state.favorite.includes(n.id)?'Remove from':'Add to'} favorites" aria-pressed="${state.favorite.includes(n.id)}" style="${state.favorite.includes(n.id)?'color:#bb425d':''}">${icon('heart')}</button><button data-action="note-menu" aria-label="More note actions">${icon('more')}</button></div></div><div class="detail-art">${art(n.art)}</div><div class="detail-type"><button data-action="change-type" aria-label="Change note type">${esc(n.type)} ${icon('edit')}</button></div><h1 class="detail-title">${esc(n.title)}</h1><a class="source-link" href="${esc(n.url)}" target="_blank" rel="noopener">${icon(n.source==='AI'?'ask':'play')}${esc(n.source)} · ${n.source==='AI'?'Composed from your notes':'Sample source'} ${icon('share')}</a><p class="trust-line">${n.source==='AI'?'Saved AI answer · Review before using':'AI-organized sample · Source details are illustrative'}</p><p class="note-body">${esc(n.summary)}</p>${n.processing?'<div class="pending-line">Link saved locally. Note preparation was interrupted. Save again to restart the demo.</div>':recipe?recipeContent(n):otherContent(n)}<div class="note-actions"><button data-action="organize">${icon('folder')}${n.collections.length?'Collections':'Add to collection'}</button><button data-action="ask-note">${icon('ask')}Ask this note</button></div>${n.collections.length?`<p class="hint">In ${n.collections.map(esc).join(' and ')}</p>`:''}<div class="personal-note"><h3>Your note to self</h3><p>${esc(n.personal||'What made this worth saving?')}</p><button class="text-button" data-action="personal-note">${n.personal?'Edit your note':'Add a thought'}</button></div><p class="demo-caption space-top">Sample content for evaluating the reading experience.</p>`}
function recipeContent(n){const chick=n.id.startsWith('saved-');return `<div class="quick-facts"><div>${chick?'20':'15'} min<span>Total time</span></div><div>2<span>Servings</span></div><div>Easy<span>Effort</span></div></div><div class="note-body"><h2>${chick?'The good part':'Why save this'}</h2><p>${chick?'Crisp the chickpeas while you stir together the yogurt. A warm, crunchy dinner over something cool and creamy.':'A flexible, low-effort recipe for a busy evening. Keep the dressing separate if you are saving some for later.'}</p><h2>What you’ll need</h2>${(chick?['1 can chickpeas, drained','½ cup thick yogurt','1 lemon','A handful of fresh herbs','Olive oil, cumin, salt']:n.id==='salad'?['1 can white beans, drained','1 lemon','A handful of parsley','Olive oil and salt']:['200 g noodles','A thumb of fresh ginger','2 tbsp soy sauce','1 tbsp sesame oil','Spring onions']).map((t,i)=>`<label class="ingredient"><input type="checkbox" aria-label="${esc(t)}"><span>${t}</span></label>`).join('')}<h2>Make it</h2>${(chick?['Pat the chickpeas dry. Toss with olive oil, cumin, and salt; cook in a hot pan until crisp.','Mix the yogurt with lemon zest and a squeeze of juice. Spoon onto a plate.','Pile the chickpeas on top. Finish with fresh herbs and a little more lemon.']:n.id==='salad'?['Drain and rinse the beans, then pat them dry.','Whisk lemon juice, olive oil, and salt together.','Toss everything with parsley. Taste and adjust.']:['Cook the noodles, keeping a little of the cooking water.','Warm the ginger in sesame oil. Stir in soy sauce and a splash of the reserved water.','Toss with the noodles and finish with sliced spring onions.']).map((t,i)=>`<div class="step"><span class="step-number">${i+1}</span><p>${t}</p></div>`).join('')}</div>`}
function otherContent(n){if(n.template==='composed')return `<div class="note-body">${n.answerHtml||''}</div><h2 class="space-top">Source notes</h2>${(n.sourceIds||[]).map(id=>`<button class="source-chip" data-note="${esc(id)}">${esc(notes.find(x=>x.id===id)?.title||'Unavailable note')}</button>`).join('')}`;
 if(n.id==='kyoto')return '<div class="note-body"><h2>A slower afternoon</h2><p>The video’s idea is simple: choose a small area and explore it on foot, instead of racing between landmarks.</p><h2>Three things to keep</h2><div class="step"><span class="step-number">1</span><p>A garden walk before the busiest part of the day.</p></div><div class="step"><span class="step-number">2</span><p>A small bookshop for a browse without a schedule.</p></div><div class="step"><span class="step-number">3</span><p>A tea stop, with enough time to sit down.</p></div><div class="small-panel"><h3>Worth checking</h3><p>The sample source doesn’t name exact venues or provide current opening hours.</p></div></div>';
 if(n.id==='ideas')return '<div class="note-body"><h2>The idea in a minute</h2><p>Small pauses give your attention somewhere to wander. Filling every gap with input can make it harder to notice your own ideas.</p><h2>Try this</h2><p>Take one short walk without headphones. When you get home, write down the thought that stayed with you.</p></div>';
 return `<div class="note-body"><h2>Worth remembering</h2><p>${esc(n.summary)}</p><h2>Before you go further</h2><p>${n.id==='cafe'?'Check opening hours and availability at the original source.':'Check current details at the original source before making a decision.'}</p></div>`;
}
function render(){
 $('#app').innerHTML=state.detail?detail():({library,search,ask}[state.tab]||library)();
 $('#save-dock').innerHTML=!state.detail&&state.tab!=='ask'?`<button class="save-button" data-action="save">${icon('plus')} Save a link</button>`:'';
 $('#navigation').innerHTML=['library','search','ask'].map(t=>`<button data-tab="${t}" class="${state.tab===t?'active':''}" ${state.tab===t?'aria-current="page"':''}>${icon(t)}${{library:'Library',search:'Search',ask:'Ask'}[t]}</button>`).join('');
 const words={library:['A library that feels like yours.','Recognizable covers, useful previews, and an easy way back into what you saved. No filing required.'],search:['Find the idea. Forget the exact title.','Search is for finding a saved object. Filters stay visible, and a useful result is one tap away.'],ask:['Useful answers, with their sources.','The selected scope is explicit. Every grounded answer leads back to the notes that informed it.']};
 $('#inspector-title').textContent=state.detail?'The useful part, beautifully clear.':words[state.tab][0];$('#inspector-copy').textContent=state.detail?'Practical steps, a visible source, and your own thoughts. Reading leads naturally to doing.':words[state.tab][1];
}
let sheetOpener;
function sheet(title,body){sheetOpener=document.activeElement;$('#sheet').innerHTML=`<div class="sheet-head"><h2 id="sheet-title">${title}</h2><button class="close" data-action="close" aria-label="Close dialog">×</button></div>${body}`;if(!$('#sheet').open)$('#sheet').showModal()}
function closeSheet(){$('#sheet').close();if(sheetOpener?.isConnected)sheetOpener.focus()}
function saveSheet(){sheet('Save a link',`<p class="sheet-copy">Keep the good part. We’ll turn the link into a useful note.</p><form id="save-form"><label class="field-label" for="save-url">Video or webpage link</label><input id="save-url" type="url" required placeholder="https://…" autocomplete="url"><button type="button" class="sample-link" data-action="sample-url">${icon('play')}Try a sample cooking video</button><label class="field-label" for="save-thought">A thought for later <span class="subtle">(optional)</span></label><input id="save-thought" type="text" placeholder="This would be great for dinner"><p class="sheet-help">No need to choose a category. You can add it to a collection later.</p><div id="save-error" role="alert"></div><button class="primary">Save link</button></form><button class="text-button" data-action="capture-help">Save directly from other apps</button><p class="demo-caption">Demo only. No link is downloaded or sent to AI.</p>`)}
function saveLink(){const value=$('#save-url').value.trim();let url;try{url=new URL(value);if(!['https:','http:'].includes(url.protocol))throw Error()}catch{$('#save-error').innerHTML='<p class="error">Enter a complete http or https link.</p>';return}
 const existing=notes.find(n=>!n.processing&&n.url.replace(/\/$/,'')===url.href.replace(/\/$/,''));if(existing){sheet('Already in your library',`<p class="sheet-copy">This link already has a note. Open it to keep reading or change its collection.</p><button class="primary" data-note="${existing.id}">Open saved note</button>`);return}
 notes=notes.filter(n=>!(n.processing&&n.url===url.href));const personal=$('#save-thought').value;const sample=url.hostname==='example.com'&&url.pathname==='/clipnote-demo/chickpeas';const id='saved-'+Date.now();state.job={id,status:'processing',url:url.href};notes.unshift({id,template:sample?'recipe':'generic',title:sample?'Crispy chickpeas, lemon & herby yogurt':'Your saved link',type:sample?'Recipes':'Ideas',art:sample?'salad':'ideas',summary:sample?'A crisp, creamy, 20-minute dinner from a short video.':'Link retained in this prototype. Live extraction is not connected.',source:sample?'Instagram':'Website',age:'Just now',url:url.href,collections:[],personal,date:'recent',processing:true});persist();
 sheet('Link saved',`<div class="success-content"><div class="success-mark">${icon('check')}</div><h2>It’s safely in your library.</h2><p>Your note is being made. You can get on with your day.</p></div><div class="job-card">${icon('clock')}<div>Making your note<small>We’ll show it in your library when it’s ready.</small></div></div><button class="primary" data-action="done-save">Back to library</button><p class="demo-caption">Simulated save and processing.</p>`);
 render();clearTimeout(saveLink.timer);saveLink.timer=setTimeout(()=>{const saved=notes.find(n=>n.id===id);if(!saved)return;saved.processing=false;state.job={id,status:'ready'};persist();if(!state.detail&&state.tab==='library')render();if($('#sheet').open&&$('#sheet-title').textContent==='Link saved')sheet('Your note is ready',`<div class="success-content"><div class="success-mark">${icon('check')}</div><h2>Ready when you are.</h2><p>${sample?'Your video is now a recipe with ingredients and clear steps.':'Your sample source card is ready. Live extraction is not connected.'}</p></div><button class="primary" data-note="${id}">Open note</button><button class="secondary" data-action="close">Keep browsing</button>`);else toast('Your saved note is ready. Open it from your library.');},2000);
}
function organize(){const n=notes.find(n=>n.id===state.detail);sheet('Add to collections',`<p class="sheet-copy">Keep “${esc(n.title)}” in any places that make sense to you.</p><form id="collection-form">${collections.map(c=>`<label class="collection-option"><input type="checkbox" name="collection" value="${esc(c)}" ${n.collections.includes(c)?'checked':''}>${esc(c)}</label>`).join('')}<button class="primary space-top">Save collections</button></form><button class="text-button" data-action="new-collection">Create a collection</button>`)}
const actions={
 close:closeSheet,save:saveSheet,back,help:()=>sheet('About this prototype','<p class="sheet-copy">An independent mobile design concept for Clipnote. All notes, sources, illustrations, AI responses, and processing are sample data. No live account or API is connected.</p><div class="small-panel"><h3>Try the whole journey</h3><p>Save the sample video, open its recipe, add it to a collection, search for dinner, and ask what you can cook.</p></div><button class="secondary" data-action="reset-demo">Reset sample library</button>'),
 'sample-url':()=>{$('#save-url').value='https://example.com/clipnote-demo/chickpeas';$('#save-url').focus()},
 'done-save':()=>{closeSheet();state.segment='Notes';state.filter='All';navigate('library')},
 job:()=>{if(state.job.status==='ready')openNote(state.job.id);else sheet('Making your note','<p class="sheet-copy">Your link is saved. You can close this and keep browsing while we make the note.</p><button class="primary" data-action="close">Keep browsing</button>')},
 'clear-search':()=>{state.query='';$('#search-input').value='';$('#search-results').innerHTML=searchResults();$('#search-input').focus()},
 'reset-filters':()=>{state.searchType='All types';state.searchSource='All sources';render()},
 'reset-search':()=>{state.query='';state.searchType='All types';state.searchSource='All sources';render();$('#search-input').focus()},
 'all-collections':()=>{state.collection=null;render()},
 'new-collection':()=>sheet('New collection',`<p class="sheet-copy">Give a plan, interest, or project a place to grow.</p><form id="new-collection-form"><label class="field-label" for="collection-name">Collection name</label><input id="collection-name" type="text" maxlength="60" required placeholder="e.g. A weekend away"><div id="collection-error" role="alert"></div><button class="primary space-top">Create collection</button></form>`),
 'ask-collection':()=>{state.scope=state.collection;state.answer=null;navigate('ask')},
 'ask-results':()=>{state.resultQuery=[state.query,state.searchType,state.searchSource].join(' · ');state.draft=state.query;state.resultIds=matches().map(n=>n.id);state.scope='Search results';state.answer=null;navigate('ask')},
 'ask-note':()=>{state.scope='Note:'+state.detail;state.answer=null;navigate('ask')},
 'new-question':()=>{state.answer=null;render()},
 favorite:()=>{const i=state.favorite.indexOf(state.detail);if(i<0)state.favorite.push(state.detail);else state.favorite.splice(i,1);persist();render();toast(i<0?'Added to favorites':'Removed from favorites')},organize,
 'change-type':()=>{const n=notes.find(n=>n.id===state.detail);sheet('Change note type',`<p class="sheet-copy">Types describe what a note is. Collections describe what you want to do with it.</p><form id="type-form"><label class="field-label" for="note-type">Type</label><select id="note-type">${['Recipes','Places','Ideas','Products','Travel','Workout','Entertainment','Other'].map(t=>`<option ${n.type===t?'selected':''}>${t}</option>`).join('')}</select><button class="primary space-top">Save type</button></form>`)},
 'personal-note':()=>{const n=notes.find(n=>n.id===state.detail);sheet('Your note to self',`<form id="personal-form"><label class="field-label" for="personal-text">What do you want to remember?</label><textarea id="personal-text">${esc(n.personal||'')}</textarea><button class="primary space-top">Save thought</button></form>`)},
 'note-menu':()=>sheet('Note actions',`<button class="menu-row" data-action="organize">Add to collection ${icon('folder')}</button><button class="menu-row" data-action="personal-note">Add your own thought ${icon('edit')}</button><button class="menu-row" data-action="change-type">Change note type ${icon('edit')}</button><button class="menu-row" data-action="source-info">About this source ${icon('info')}</button>`),
 'source-info':()=>sheet('About this source','<p class="sheet-copy">This is illustrative note content for the prototype. A production note should say what was actually available: video, transcript, caption, or webpage text.</p><div class="small-panel"><h3>When something is missing</h3><p>Keep the source link and explain the limit. Never invent quantities, locations, or timestamps.</p></div>'),
 'capture-help':()=>sheet('Save from where you are','<div class="small-panel"><h3>iPhone web app</h3><p>Use your configured Clipnote Shortcut, or copy a link and paste it here. Installing a web app alone doesn’t make it an iOS share destination.</p></div><div class="small-panel"><h3>Supported Android browsers</h3><p>Install the web app, then choose Clipnote from the system share sheet where Web Share Target is supported.</p></div><div class="small-panel"><h3>Native iPhone app</h3><p>The proposed share extension receives the link directly. Enable it in the system share sheet when that app is available.</p></div>'),
 settings:()=>sheet('Your library, your way',`<button class="menu-row" data-action="capture-help">Save from other apps ${icon('share')}</button><button class="menu-row" data-action="digest-info">Weekly digest ${icon('book')}</button><button class="menu-row" data-action="help">About this prototype ${icon('info')}</button><p class="sheet-help">Privacy, account, region, appearance, and billing settings are described in the UX specification.</p>`),
 'digest-info':()=>sheet('A weekly way back','<p class="sheet-copy">The proposed digest brings together a few useful saves with direct links back to each note. Email is optional; daily reminders are not part of this design.</p><p class="sheet-help">This prototype does not subscribe you or send email.</p>'),
 'reset-demo':()=>{clearTimeout(saveLink.timer);notes=structuredClone(initialNotes);collections=['Weeknight cooking','Japan, someday','Around the city','For the home'];notes.forEach(n=>n.template=n.type==='Recipes'?'recipe':'generic');state.favorite=[];state.draft='';state.job=null;state.answer=null;state.segment='Notes';state.filter='All';state.collection=null;state.query='';state.scope='All notes';state.searchType='All types';state.searchSource='All sources';persist();closeSheet();navigate('library');toast('Sample library reset')},
 'save-answer':()=>{const a=state.answer;if(!a?.ids.length)return;if(a.savedId){openNote(a.savedId);return}const id='answer-'+Date.now();a.savedId=id;notes.unshift({id,template:'composed',title:a.title,type:'Ideas',art:'ideas',summary:'A useful answer composed from your saved notes.',source:'AI',age:'Just now',url:'https://example.com/sample/ai-answer',collections:[],sourceIds:a.ids,answerHtml:a.html,date:'recent'});persist();sheet('Answer saved',`<p class="sheet-copy">It’s in your library, with the notes it came from.</p><button class="primary" data-note="${id}">Open saved answer</button><button class="secondary" data-action="close">Back to conversation</button>`)}
};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.action){actions[b.dataset.action]?.();return}if(b.dataset.tab){navigate(b.dataset.tab);return}if(b.dataset.note){if($('#sheet').open)closeSheet();openNote(b.dataset.note);return}if(b.dataset.segment){state.segment=b.dataset.segment;state.collection=null;render();return}if(b.dataset.filter){state.filter=b.dataset.filter;render();return}if(b.dataset.collection){state.collection=b.dataset.collection;state.segment='Collections';render();return}if(b.dataset.query){state.query=b.dataset.query;render();return}if(b.dataset.question){generateAnswer(b.dataset.question);return}if(b.dataset.tour){const t=b.dataset.tour;if(t==='save'){saveSheet();return}if(t==='note'){openNote('noodles');return}if(t==='collections'){state.segment='Collections';state.collection=null;navigate('library');return}navigate(t);}});
document.addEventListener('input',e=>{if(e.target.id==='question')state.draft=e.target.value;if(e.target.id==='search-input'){state.query=e.target.value;$('#search-results').innerHTML=searchResults()}});
document.addEventListener('change',e=>{if(e.target.id==='search-type'){state.searchType=e.target.value;$('#search-results').innerHTML=searchResults()}if(e.target.id==='search-source'){state.searchSource=e.target.value;$('#search-results').innerHTML=searchResults()}if(e.target.id==='ask-scope'){state.scope=e.target.value;state.answer=null;render()}});
document.addEventListener('submit',e=>{e.preventDefault();const id=e.target.id;
 if(id==='save-form')saveLink();
 if(id==='ask-form'){const q=$('#question').value.trim();if(q)generateAnswer(q)}
 if(id==='collection-form'){notes.find(n=>n.id===state.detail).collections=[...e.target.querySelectorAll('input:checked')].map(i=>i.value);persist();closeSheet();render();toast('Collections updated')}
 if(id==='new-collection-form'){const name=$('#collection-name').value.trim();if(!name||collections.some(c=>c.toLowerCase()===name.toLowerCase())){$('#collection-error').innerHTML='<p class="error">Choose a new collection name.</p>';return}collections.push(name);persist();if(state.detail)organize();else{closeSheet();state.segment='Collections';state.collection=name;navigate('library')}toast('Collection created')}
 if(id==='personal-form'){notes.find(n=>n.id===state.detail).personal=$('#personal-text').value;persist();closeSheet();render();toast('Your thought is saved')}
 if(id==='type-form'){notes.find(n=>n.id===state.detail).type=$('#note-type').value;persist();closeSheet();render();toast('Note type updated')}
});
$('#sheet').addEventListener('click',e=>{if(e.target===$('#sheet')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeSheet()}});
window.addEventListener('hashchange',()=>{const hash=location.hash.slice(1);if(hash.startsWith('note/')){state.detail=hash.slice(5)}else if(['library','search','ask'].includes(hash)){state.tab=hash;state.detail=null}render()});
if(location.hash.startsWith('#note/'))state.detail=location.hash.slice(6);else if(['#library','#search','#ask'].includes(location.hash))state.tab=location.hash.slice(1);render();
